import { AxiosError } from 'axios'
import { useState } from 'react'
import { useIsAuthenticated } from 'react-auth-kit'
import { Helmet } from 'react-helmet-async'
import { Navigate, useNavigate, useParams } from 'react-router'

import AccessTimeIcon from '@mui/icons-material/AccessTime'
import ArrowForwardIcon from '@mui/icons-material/ArrowForward'
import LaunchIcon from '@mui/icons-material/Launch'
import LockRoundedIcon from '@mui/icons-material/LockRounded'
import PlaceIcon from '@mui/icons-material/Place'
import StorefrontIcon from '@mui/icons-material/Storefront'
import {
  Box,
  Button,
  Card,
  CardMedia,
  Chip,
  CircularProgress,
  Container,
  Dialog,
  Divider,
  Stack,
  Typography,
  useMediaQuery,
  useTheme
} from '@mui/material'

import { COMMON_MESSAGE } from 'src/data/messages'
import {
  PARTNER_COUPON_MESSAGES,
  PARTNER_COUPON_UNLOCK_TYPE_LABELS,
  PARTNER_COUPON_USAGE_TYPE_LABELS
} from 'src/data/partnerBenefits'

import {
  formatPartnerBenefitDate,
  getDateInputValue,
  getDateInputValueFromString,
  getIsPartnerCouponLocked
} from 'src/utils/partnerBenefits'

import { usePartnerBenefits, usePartnerCouponDetail } from 'src/hooks/usePartnerBenefits'

interface DetailTextProps {
  label: string
  value?: string
}

interface DetailAccentBlockProps {
  label: string
  backgroundColor: string
  children: React.ReactNode
}

const DetailText: React.FC<DetailTextProps> = ({ label, value }) => {
  if (!value) return null

  return (
    <Box>
      <Typography variant="caption" color="text.secondary">
        {label}
      </Typography>
      <Typography sx={{ mt: 0.75, lineHeight: 1.7, wordBreak: 'keep-all' }}>{value}</Typography>
    </Box>
  )
}

const DetailAccentBlock: React.FC<DetailAccentBlockProps> = ({ label, backgroundColor, children }) => {
  const theme = useTheme()

  return (
    <Box
      sx={{
        minHeight: '100%',
        bgcolor: backgroundColor,
        borderRadius: theme.general.borderRadius,
        px: { xs: 2, md: 2.25 },
        py: { xs: 1.5, md: 1.75 }
      }}
    >
      <Typography variant="caption" sx={{ color: theme.palette.text.primary, fontWeight: 700 }}>
        {label}
      </Typography>
      <Box sx={{ mt: 0.75 }}>{children}</Box>
    </Box>
  )
}

const BenefitCouponDetailPage: React.FC = () => {
  const theme = useTheme()
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'))
  const navigate = useNavigate()
  const { couponId } = useParams()
  const isAuthenticated = useIsAuthenticated()
  const couponIdNumber = Number(couponId)
  const isCouponIdInvalid = Number.isNaN(couponIdNumber)
  const {
    data: partnerCouponItem,
    error,
    isError,
    isLoading,
    refetch: refetchPartnerCoupon
  } = usePartnerCouponDetail(isCouponIdInvalid ? undefined : couponIdNumber)
  const { usePartnerCoupon } = usePartnerBenefits({ isQueryEnabled: false })
  const [isGuideDialogOpen, setIsGuideDialogOpen] = useState(false)
  const [isImageError, setIsImageError] = useState(false)

  const handleRetryButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    refetchPartnerCoupon()
  }

  if (!isAuthenticated()) {
    return (
      <>
        <Helmet>
          <title>쿠폰 혜택 - KLUB</title>
        </Helmet>
        <Container maxWidth="sm" sx={{ py: { xs: 4, md: 8 } }}>
          <Card sx={{ p: { xs: 3, md: 4 }, textAlign: 'center', boxShadow: theme.header.boxShadow }}>
            <Typography variant="h3" sx={{ mb: 1.5 }}>
              로그인이 필요합니다
            </Typography>
            <Typography color="text.secondary" sx={{ mb: 3 }}>
              제휴 쿠폰 상세 정보는 로그인 후 확인할 수 있습니다.
            </Typography>
            <Button variant="contained" onClick={() => navigate('/auth/login')} endIcon={<ArrowForwardIcon />}>
              로그인하기
            </Button>
          </Card>
        </Container>
      </>
    )
  }

  if (isLoading) {
    return (
      <Container maxWidth="lg" sx={{ py: { xs: 4, md: 8 }, textAlign: 'center' }}>
        <CircularProgress />
      </Container>
    )
  }

  if (isCouponIdInvalid) {
    return <Navigate to="/status/404" replace />
  }

  if (isError) {
    if (error instanceof AxiosError && error.response?.status === 404) {
      return <Navigate to="/status/404" replace />
    }

    return (
      <>
        <Helmet>
          <title>쿠폰 혜택 - KLUB</title>
        </Helmet>
        <Container maxWidth="sm" sx={{ py: { xs: 4, md: 8 } }}>
          <Card sx={{ p: { xs: 3, md: 4 }, textAlign: 'center', boxShadow: theme.header.boxShadow }}>
            <Typography variant="h3" sx={{ mb: 1.5 }}>
              쿠폰 정보를 불러오지 못했습니다
            </Typography>
            <Typography color="text.secondary" sx={{ mb: 3 }}>
              {COMMON_MESSAGE.LOAD_FAIL}
            </Typography>
            <Button variant="contained" onClick={handleRetryButtonClick}>
              다시 시도
            </Button>
          </Card>
        </Container>
      </>
    )
  }

  if (!partnerCouponItem) {
    return <Navigate to="/status/404" replace />
  }

  const { coupon, store } = partnerCouponItem
  const isLocked = getIsPartnerCouponLocked(coupon)
  const isDateAvailable =
    getDateInputValueFromString(coupon.startDate) <= getDateInputValue() &&
    getDateInputValue() <= getDateInputValueFromString(coupon.endDate)

  const handleUseButtonClick: React.MouseEventHandler<HTMLButtonElement> = async () => {
    if (isLocked) return

    try {
      await usePartnerCoupon(coupon.id)
    } catch {
      return
    }

    setIsGuideDialogOpen(true)
  }

  const handleMapButtonClick: React.MouseEventHandler<HTMLButtonElement> = () => {
    window.open(store.mapLink, '_blank', 'noopener,noreferrer')
  }

  const handleGuideDialogClose: React.MouseEventHandler<HTMLButtonElement> = () => {
    setIsGuideDialogOpen(false)
  }

  const handleCouponImageError: React.ReactEventHandler<HTMLImageElement> = () => {
    setIsImageError(true)
  }

  return (
    <>
      <Helmet>
        <title>{store.name} 쿠폰 혜택 - KLUB</title>
      </Helmet>
      <Container maxWidth="lg" sx={{ py: { xs: 2, md: 4 } }}>
        <Card data-testid="benefit-coupon-detail" sx={{ p: { xs: 2, md: 3 }, boxShadow: theme.header.boxShadow }}>
          <Box
            sx={{
              width: '100%',
              aspectRatio: { xs: '16 / 10', md: '21 / 6' },
              bgcolor: theme.colors.alpha.black[5],
              borderRadius: theme.general.borderRadiusLg,
              overflow: 'hidden',
              mb: 2.5
            }}
          >
            {store.imageUrl && !isImageError ? (
              <CardMedia
                component="img"
                image={store.imageUrl}
                alt={`${store.name} 이미지`}
                onError={handleCouponImageError}
                sx={{ width: '100%', height: '100%', objectFit: 'cover' }}
              />
            ) : (
              <Box
                sx={{
                  width: '100%',
                  height: '100%',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: theme.colors.alpha.black[30]
                }}
              >
                <StorefrontIcon sx={{ fontSize: 72 }} />
              </Box>
            )}
          </Box>

          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1, mb: 1.5 }}>
            <Chip label="동아리 회원 전용" size="small" />
            <Chip label={PARTNER_COUPON_USAGE_TYPE_LABELS[coupon.usageType]} size="small" />
            {isLocked && (
              <Chip
                icon={<LockRoundedIcon />}
                label={PARTNER_COUPON_UNLOCK_TYPE_LABELS[coupon.unlockType]}
                color="warning"
                size="small"
                variant="outlined"
              />
            )}
          </Box>

          <Typography variant={isMobile ? 'h4' : 'h3'} sx={{ mb: 2 }}>
            {store.name}
          </Typography>

          <Box
            sx={{
              border: `1px solid ${theme.colors.error.light}`,
              bgcolor: theme.colors.error.lighter,
              borderRadius: theme.general.borderRadius,
              px: { xs: 2, md: 2.5 },
              py: { xs: 1.5, md: 2 },
              mb: 2.5
            }}
          >
            <Typography
              sx={{
                color: theme.colors.error.dark,
                fontWeight: 700,
                fontSize: { xs: 19, md: 24 },
                lineHeight: 1.45,
                wordBreak: 'keep-all'
              }}
            >
              {coupon.benefitContent}
            </Typography>
          </Box>

          <Box
            sx={{
              display: 'grid',
              gridTemplateColumns: { xs: '1fr', md: '1fr 1fr' },
              gap: { xs: 2, md: 3 },
              mb: 3
            }}
          >
            <DetailAccentBlock label="사용 대상" backgroundColor={theme.colors.primary.lighter}>
              <Typography sx={{ fontWeight: 700, lineHeight: 1.7, wordBreak: 'keep-all' }}>
                {coupon.audience}
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                인증 방식: {coupon.verificationMethod}
              </Typography>
            </DetailAccentBlock>
            <DetailAccentBlock label="쿠폰 사용 기간" backgroundColor={theme.colors.info.lighter}>
              <Stack direction="row" spacing={1} alignItems="center" sx={{ fontWeight: 700 }}>
                <AccessTimeIcon color="info" fontSize="small" />
                <Typography sx={{ fontWeight: 700 }}>
                  {formatPartnerBenefitDate(coupon.startDate)} - {formatPartnerBenefitDate(coupon.endDate)}
                </Typography>
              </Stack>
              <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                사용 가능 기간 내 매장 운영 시간에 사용할 수 있습니다.
              </Typography>
            </DetailAccentBlock>
          </Box>

          <Box
            sx={{
              display: 'grid',
              gridTemplateColumns: { xs: '1fr', md: '1fr 1fr' },
              gap: { xs: 2, md: 5 },
              px: { xs: 0, md: 2 },
              mb: 3
            }}
          >
            <Stack spacing={2.5}>
              <DetailText label="추천 메뉴" value={coupon.recommendedMenu} />
              <DetailText label="사용 방법" value={coupon.howToUse} />
              <Box>
                <Typography variant="caption" color="text.secondary">
                  위치
                </Typography>
                <Stack direction="row" spacing={1} alignItems="center" sx={{ mt: 0.75 }}>
                  <PlaceIcon color="primary" fontSize="small" />
                  <Typography>{store.address || store.locationLabel || '지도 링크에서 위치 확인'}</Typography>
                </Stack>
              </Box>
            </Stack>
            <Stack spacing={2.5}>
              <DetailText label="사용 조건" value={coupon.audience} />
              <DetailText label="유의사항" value={coupon.notice} />
              {isLocked && (
                <DetailText
                  label="잠금 해제 방식"
                  value={PARTNER_COUPON_UNLOCK_TYPE_LABELS[coupon.lockReason ?? coupon.unlockType]}
                />
              )}
            </Stack>
          </Box>

          <Divider sx={{ mb: 2.5 }} />

          <Stack direction={{ xs: 'column', md: 'row' }} spacing={1.5}>
            <Button
              variant="contained"
              disabled={isLocked || !isDateAvailable}
              onClick={handleUseButtonClick}
              fullWidth
            >
              {isLocked ? '후기 작성 후 잠금해제' : isDateAvailable ? '쿠폰 사용 안내 보기' : '사용 기간이 아닙니다'}
            </Button>
            <Button variant="outlined" onClick={handleMapButtonClick} endIcon={<LaunchIcon />} fullWidth>
              위치 보기
            </Button>
          </Stack>
        </Card>
      </Container>
      <Dialog open={isGuideDialogOpen} onClose={() => setIsGuideDialogOpen(false)}>
        <Box sx={{ p: 3, maxWidth: 420 }}>
          <Typography variant="h4" sx={{ mb: 1.5 }}>
            쿠폰 사용 안내
          </Typography>
          <Typography sx={{ lineHeight: 1.7, wordBreak: 'keep-all' }}>
            {PARTNER_COUPON_MESSAGES.USE_GUIDE} 쿠폰 사용 기록이 저장되었습니다.
          </Typography>
          <Box sx={{ display: 'flex', justifyContent: 'flex-end', mt: 2 }}>
            <Button variant="contained" onClick={handleGuideDialogClose}>
              확인
            </Button>
          </Box>
        </Box>
      </Dialog>
    </>
  )
}

export default BenefitCouponDetailPage
